export const getRewrapInvoiceKeyUrl = (invoiceId: string,) => {




  return `/api/invoices/${invoiceId}/rewrap`
}

/**
 * When the other party on an invoice lost their key and reset it, their wrapped copy of the envelope key became useless and was removed. The party that still holds a working copy unwraps it in their browser, re-wraps it for the counterparty's NEW public key, and stores it here - the same mechanics as a grant, but restoring one of the invoice's two permanent copies. The server never sees plaintext or private keys.
 * @summary Re-share this envelope with the other party after they reset their key
 */
export const rewrapInvoiceKey = async (invoiceId: string,
    rewrapKeyInput: RewrapKeyInput, options?: Parameters<typeof customFetch>[1]): Promise<Invoice> => {

  return customFetch<Invoice>(getRewrapInvoiceKeyUrl(invoiceId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(rewrapKeyInput)
  }
);}





